	@Test
	public void nestedAggregateRowCorrelatedServiceReportsItsProjectedInputDependency() {
		String query = "SELECT ?var ?cnt WHERE { "
				+ "SERVICE <urn:provider> { SELECT ?var { ?s ?p ?var } LIMIT 2 } "
				+ "SERVICE <urn:aggregate> { SELECT ?var ?cnt ?__rowIdx WHERE { "
				+ "SELECT (COUNT(?s2) AS ?cnt) WHERE { ?s2 ?p2 ?var } } } "
				+ "}";

		QueryRoot root = optimizedRoot(query);
		Service provider = findServices(root).stream()
				.filter(service -> !service.hasRowIndexProjection()
						&& service.getServiceOutputBindingNames().contains("var"))
				.findFirst()
				.orElseThrow(() -> new AssertionError("missing provider SERVICE output var"));
		Service dependent = rowCorrelatedService(root, "cnt");
		assertThat(provider).isNotSameAs(dependent);
		assertThat(provider.getServiceOutputBindingNames()).contains("var");
		assertThat(dependent.hasRowIndexProjection()).isTrue();
		assertThat(dependent.getServiceVars()).contains("var");
		assertThat(dependent.getServiceInputBindingNames())
				.as("the outer projected var is injected into the nested aggregate per row")
				.contains("var");
		assertConsumerHasProviderPrefix(dependent, "var");
	}

