	@Test
	public void rowCorrelatedServiceWaitsForEveryPossibleProviderOfJaggedBinding() {
		String query = "SELECT ?x ?output WHERE { "
				+ "VALUES ?x { UNDEF } "
				+ "SERVICE <urn:provider-two> { SELECT ?x { ?s ?p ?x } } "
				+ "SERVICE <urn:consumer> { SELECT (CONCAT(?x, '_processed') AS ?output) ?__rowIdx WHERE { } } "
				+ "}";

		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public double getCardinality(TupleExpr expr) {
				if (expr instanceof Service service && service.getServiceRef().hasValue()) {
					String endpoint = service.getServiceRef().getValue().stringValue();
					if ("urn:provider-two".equals(endpoint)) {
						return 100_000;
					}
					if ("urn:consumer".equals(endpoint)) {
						return 1;
					}
				}
				return super.getCardinality(expr);
			}
		};

		ParsedQuery parsedQuery = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		QueryRoot root = new QueryRoot(parsedQuery.getTupleExpr());
		new QueryJoinOptimizer(statistics, new EmptyTripleSource()).optimize(root, null, null);

		Service dependent = rowCorrelatedService(root, "output");
		Service secondProvider = serviceAtEndpoint(root, "urn:provider-two");
		BindingSetAssignment possibleUndefinedProvider = findBindingSetAssignments(root).stream()
				.filter(assignment -> assignment.getBindingNames().contains("x")
						&& containsUndefinedBinding(assignment, "x"))
				.findFirst()
				.orElseThrow(() -> new AssertionError("missing jagged VALUES provider"));

		assertConsumerPrefixContains(dependent, possibleUndefinedProvider, secondProvider);
	}

