	@Test
	public void rowCorrelatedServiceWaitsForAllProviderInputs() {
		String query = "SELECT ?x ?label ?output WHERE { "
				+ "SERVICE <urn:dummy> { SELECT ?x { ?s ?p ?x } } "
				+ "SERVICE <urn:dummy> { SELECT ?label { ?s ?p ?label } } "
				+ "SERVICE <urn:dummy> { SELECT (CONCAT(?x, ?label) AS ?output) ?__rowIdx WHERE { } } "
				+ "}";

		QueryRoot root = optimizedRoot(query);
		Service dependent = rowCorrelatedService(root, "output");
		List<Service> providers = findServices(root).stream()
				.filter(service -> !service.hasRowIndexProjection())
				.toList();
		assertThat(providers).hasSize(2);
		HashSet<String> providerOutputs = new HashSet<>();
		for (Service provider : providers) {
			providerOutputs.addAll(provider.getServiceOutputBindingNames());
			assertThat(provider.getServiceInputBindingNames()).isEmpty();
		}
		assertThat(providerOutputs).contains("x", "label");
		assertThat(dependent.hasRowIndexProjection()).isTrue();
		assertThat(dependent.getServiceInputBindingNames()).contains("x", "label");
		assertConsumerHasProviderPrefix(dependent, "x", "label");
	}

