	@Test
	public void cyclicRowCorrelatedServicesUseStableSourceOrder() {
		String query = "SELECT ?a ?b WHERE { "
				+ "SERVICE <urn:service-a> { SELECT (CONCAT(?b, '_a') AS ?a) ?__rowIdx WHERE { } } "
				+ "SERVICE <urn:service-b> { SELECT (CONCAT(?a, '_b') AS ?b) ?__rowIdx WHERE { } } "
				+ "}";

		QueryRoot root = optimizedRoot(query);
		Join join = topLevelJoin(root);

		assertThat(join.getLeftArg()).isInstanceOf(Service.class);
		assertThat(join.getRightArg()).isInstanceOf(Service.class);
		Service first = (Service) join.getLeftArg();
		Service second = (Service) join.getRightArg();
		assertThat(first.getServiceOutputBindingNames()).contains("a");
		assertThat(first.getServiceInputBindingNames()).contains("b");
		assertThat(second.getServiceOutputBindingNames()).contains("b");
		assertThat(second.getServiceInputBindingNames()).contains("a");
	}

